// HAND-WRITTEN TEST — NOT generated by openapi-generator (zz_ prefix +
// _test.go suffix keep it clear of regeneration and non-test builds).
//
// The Cryptography Provider v2 contract uses two oneOf wrappers that discriminate
// on the JSON property keyRequestType ("secret" or "keyPair"). Both variants in
// each wrapper share the same Go struct shape and would cause the generator's
// match-counting decoder to fail. tools/fixoneof patches in a discriminator-aware
// decoder; these tests fail if a regeneration ever ships the stock version.
//
// DISPATCH CONTRACT (matches the spec, encoded in tools/fixoneof):
//   - KeyCreationResponseInterface switches on STRING "keyRequestType"
//     ("secret" -> SecretKeyDataResponseV2Dto; "keyPair" -> KeyPairDataResponseV2Dto).
//   - KeyCreationStatusResponseInterface switches on STRING "keyRequestType"
//     ("secret" -> SecretKeyOperationStatusResponseV2Dto; "keyPair" -> KeyPairOperationStatusResponseV2Dto).
//   - Both wrappers require the discriminator field in their variants.
package v2

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

// The generator's stock oneOf UnmarshalJSON tries every variant and fails when
// two share a Go shape. tools/fixoneof replaces it with a discriminator-aware
// decoder; these tests fail if a regeneration ever ships the stock version.

type oneOfWrapperKC interface {
	json.Unmarshaler
	json.Marshaler
}

type oneOfCaseKC struct {
	name           string
	payload        string
	newWrapper     func() oneOfWrapperKC
	wantType       interface{} // pointer to the expected concrete variant
	discSubstr     []string    // must survive a marshal round-trip
	mustNotContain []string    // Go field names that must not appear in marshalled JSON
}

// assertExactlyOneVariant checks that exactly one pointer field on the wrapper is non-nil.
// This ensures mutual exclusivity of oneOf variants.
func assertExactlyOneVariant(t *testing.T, wrapper string, w interface{}) {
	t.Helper()
	rv := reflect.ValueOf(w)
	if rv.Kind() != reflect.Ptr {
		t.Fatalf("%s: expected pointer, got %v", wrapper, rv.Kind())
	}

	// Dereference to struct
	rv = rv.Elem()
	if rv.Kind() != reflect.Struct {
		t.Fatalf("%s: expected struct behind pointer, got %v", wrapper, rv.Kind())
	}

	nonNilCount := 0
	for i := 0; i < rv.NumField(); i++ {
		fv := rv.Field(i)
		// Check if field is a pointer type
		if fv.Kind() == reflect.Ptr && !fv.IsNil() {
			nonNilCount++
		}
	}

	if nonNilCount != 1 {
		t.Fatalf("%s: expected exactly 1 non-nil variant pointer, found %d", wrapper, nonNilCount)
	}
}

func runCasesKC(t *testing.T, wrapper string, cases []oneOfCaseKC) {
	t.Helper()
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			wantT := reflect.TypeOf(tc.wantType)

			w := tc.newWrapper()
			if err := json.Unmarshal([]byte(tc.payload), w); err != nil {
				t.Fatalf("%s: unmarshal %s: %v", wrapper, tc.payload, err)
			}

			// Assert mutual exclusivity: exactly one variant pointer is non-nil
			assertExactlyOneVariant(t, wrapper, w)

			// For KeyCreationResponseInterface, get the variant directly
			var gotInstance interface{}
			if ki, ok := w.(*KeyCreationResponseInterface); ok {
				if ki.SecretKeyDataResponseV2Dto != nil {
					gotInstance = ki.SecretKeyDataResponseV2Dto
				} else if ki.KeyPairDataResponseV2Dto != nil {
					gotInstance = ki.KeyPairDataResponseV2Dto
				}
			} else if ki, ok := w.(*KeyCreationStatusResponseInterface); ok {
				if ki.SecretKeyOperationStatusResponseV2Dto != nil {
					gotInstance = ki.SecretKeyOperationStatusResponseV2Dto
				} else if ki.KeyPairOperationStatusResponseV2Dto != nil {
					gotInstance = ki.KeyPairOperationStatusResponseV2Dto
				}
			}

			if gotInstance == nil {
				t.Fatalf("%s: variant not populated after decoding %s", wrapper, tc.name)
			}
			if reflect.TypeOf(gotInstance) != wantT {
				t.Fatalf("%s: variant = %v, want %v", wrapper, reflect.TypeOf(gotInstance), wantT)
			}

			// Marshal and check discriminator survives
			b, err := json.Marshal(w)
			if err != nil {
				t.Fatalf("%s: marshal: %v", wrapper, err)
			}
			bstr := string(b)
			for _, sub := range tc.discSubstr {
				if !strings.Contains(bstr, sub) {
					t.Fatalf("%s: marshalled JSON missing %q\ngot: %s", wrapper, sub, b)
				}
			}
			// Check Go field names do not appear in marshalled JSON
			for _, mustNot := range tc.mustNotContain {
				if strings.Contains(bstr, `"`+mustNot+`"`) {
					t.Fatalf("%s: marshalled JSON must not contain Go field name %q\ngot: %s", wrapper, mustNot, b)
				}
			}

			// Round-trip: unmarshal the marshalled bytes
			w2 := tc.newWrapper()
			if err := json.Unmarshal(b, w2); err != nil {
				t.Fatalf("%s: round-trip unmarshal: %v\nbytes: %s", wrapper, err, b)
			}

			// Assert mutual exclusivity after round-trip
			assertExactlyOneVariant(t, wrapper, w2)

			// Check variant type is still the same
			var gotInstance2 interface{}
			if ki, ok := w2.(*KeyCreationResponseInterface); ok {
				if ki.SecretKeyDataResponseV2Dto != nil {
					gotInstance2 = ki.SecretKeyDataResponseV2Dto
				} else if ki.KeyPairDataResponseV2Dto != nil {
					gotInstance2 = ki.KeyPairDataResponseV2Dto
				}
			} else if ki, ok := w2.(*KeyCreationStatusResponseInterface); ok {
				if ki.SecretKeyOperationStatusResponseV2Dto != nil {
					gotInstance2 = ki.SecretKeyOperationStatusResponseV2Dto
				} else if ki.KeyPairOperationStatusResponseV2Dto != nil {
					gotInstance2 = ki.KeyPairOperationStatusResponseV2Dto
				}
			}

			if reflect.TypeOf(gotInstance2) != wantT {
				t.Fatalf("%s: round-trip variant = %v, want %v", wrapper, reflect.TypeOf(gotInstance2), wantT)
			}
		})
	}
}

func TestKeyCreationResponseInterfaceRoundTrip(t *testing.T) {
	runCasesKC(t, "KeyCreationResponseInterface", []oneOfCaseKC{
		{
			name: "secret",
			payload: `{
				"keyRequestType":"secret",
				"keyData":{"type":"Secret","algorithm":"RSA","length":2048}
			}`,
			newWrapper: func() oneOfWrapperKC { return &KeyCreationResponseInterface{} },
			wantType:   &SecretKeyDataResponseV2Dto{},
			discSubstr: []string{`"keyRequestType":"secret"`},
			mustNotContain: []string{
				"SecretKeyDataResponseV2Dto",
				"KeyPairDataResponseV2Dto",
			},
		},
		{
			name: "keyPair",
			payload: `{
				"keyRequestType":"keyPair",
				"publicKeyData":{
					"keyMeta":[],
					"keyData":{"type":"Public","algorithm":"RSA","length":3072,"publicKeySpki":"MIIB"}
				},
				"privateKeyData":{
					"keyMeta":[],
					"keyData":{"type":"Private","algorithm":"RSA","length":3072}
				}
			}`,
			newWrapper: func() oneOfWrapperKC { return &KeyCreationResponseInterface{} },
			wantType:   &KeyPairDataResponseV2Dto{},
			discSubstr: []string{`"keyRequestType":"keyPair"`},
			mustNotContain: []string{
				"SecretKeyDataResponseV2Dto",
				"KeyPairDataResponseV2Dto",
			},
		},
	})
}

func TestKeyCreationResponseInterfaceRejectsUnknownKeyRequestType(t *testing.T) {
	const payload = `{"keyRequestType":"quantum"}`

	var got KeyCreationResponseInterface
	if err := json.Unmarshal([]byte(payload), &got); err == nil {
		t.Fatal("expected an error for an unknown keyRequestType")
	}
}

func TestKeyCreationStatusResponseInterfaceRoundTrip(t *testing.T) {
	runCasesKC(t, "KeyCreationStatusResponseInterface", []oneOfCaseKC{
		{
			name:       "secret",
			payload:    `{"keyRequestType":"secret","status":"inProgress"}`,
			newWrapper: func() oneOfWrapperKC { return &KeyCreationStatusResponseInterface{} },
			wantType:   &SecretKeyOperationStatusResponseV2Dto{},
			discSubstr: []string{`"keyRequestType":"secret"`, `"status":"inProgress"`},
			mustNotContain: []string{
				"SecretKeyOperationStatusResponseV2Dto",
				"KeyPairOperationStatusResponseV2Dto",
			},
		},
		{
			name:       "keyPair",
			payload:    `{"keyRequestType":"keyPair","status":"completed"}`,
			newWrapper: func() oneOfWrapperKC { return &KeyCreationStatusResponseInterface{} },
			wantType:   &KeyPairOperationStatusResponseV2Dto{},
			discSubstr: []string{`"keyRequestType":"keyPair"`, `"status":"completed"`},
			mustNotContain: []string{
				"SecretKeyOperationStatusResponseV2Dto",
				"KeyPairOperationStatusResponseV2Dto",
			},
		},
	})
}
